insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-creation-1','picture',1,1,1,3,'Genesis 1:1-3',1,'Which event does this illustration depict?',null,'["The parting of the Red Sea", "Fire on Mount Carmel", "The creation of the world", "Noah''s flood"]'::jsonb,2,'Genesis opens with God creating the heaven and the earth and then calling light into being.','Think of the very first chapter of the Bible.','creation','Rays of light breaking over dark waters as land and plants emerge.','KJV',array['creation','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'In the beginning God created the heaven and the earth. And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters. And God said, Let there be light: and there was light.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-creation-2','picture',1,1,3,5,'Genesis 1:3-5',2,'According to Genesis 1, what did God create on the first day?',null,'["The sun and moon", "Light", "Land animals", "Mankind"]'::jsonb,1,'On the first day God said "Let there be light" and divided the light from the darkness.','Read Genesis 1:3-5.','creation','Rays of light breaking over dark waters as land and plants emerge.','KJV',array['creation','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And God said, Let there be light: and there was light. And God saw the light, that it was good: and God divided the light from the darkness. And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-creation-3','picture',1,1,16,19,'Genesis 1:16-19',3,'On which day does Genesis 1 describe the making of the sun, moon and stars?',null,'["The fourth day", "The sixth day", "The second day", "The first day"]'::jsonb,0,'The "two great lights" and the stars are placed in the firmament on the fourth day.','It comes after the dry land and plants.','creation','Rays of light breaking over dark waters as land and plants emerge.','KJV',array['creation','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also. And God set them in the firmament of the heaven to give light upon the earth, And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good. And the evening and the morning were the fourth day.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-creation-4','picture',1,2,2,2,'Genesis 2:2',1,'On which day did God rest from all His work?',null,'["The seventh day", "The first day", "The sixth day", "The third day"]'::jsonb,0,'Genesis 2:2 says God ended His work and rested on the seventh day.','Read Genesis 2:2.','creation','Rays of light breaking over dark waters as land and plants emerge.','KJV',array['creation','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-noah_ark-1','picture',1,8,15,19,'Genesis 8:15-19',1,'Which Bible account does this scene show?',null,'["Paul''s shipwreck", "Jonah and the great fish", "Noah and the ark", "Moses in the bulrushes"]'::jsonb,2,'After the flood God told Noah to bring every living creature out of the ark.','Read Genesis 8:15-19.','noah_ark','A large wooden ark on a hillside under a rainbow as animals walk out in pairs.','KJV',array['noah_ark','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And God spake unto Noah, saying, Go forth of the ark, thou, and thy wife, and thy sons, and thy sons’ wives with thee. Bring forth with thee every living thing that is with thee, of all flesh, both of fowl, and of cattle, and of every creeping thing that creepeth upon the earth; that they may breed abundantly in the earth, and be fruitful, and multiply upon the earth. And Noah went forth, and his sons, and his wife, and his sons’ wives with him: Every beast, every creeping thing, and every fowl, and whatsoever creepeth upon the earth, after their kinds, went forth out of the ark.') on conflict (id) do nothing;
