insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-empty_tomb-4','picture',41,16,2,2,'Mark 16:2',2,'On which day of the week did the women come to the tomb?',null,'["The sixth day", "The seventh day", "The first day of the week", "The third day"]'::jsonb,2,'They came very early in the morning the first day of the week.','Read Mark 16:2.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And very early in the morning the first day of the week, they came unto the sepulchre at the rising of the sun.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-noah','whoami',1,6,13,14,'Genesis 6:13-14',1,'Who am I?','["I lived before a great flood.", "God told me to build with gopher wood.", "My sons were Shem, Ham and Japheth.", "I built the ark."]'::jsonb,'["Abraham", "Enoch", "Lot", "Noah"]'::jsonb,3,'God told Noah, "Make thee an ark of gopher wood."','Look in Genesis.',null,null,'KJV',array['noah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth. Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-moses','whoami',2,3,2,4,'Exodus 3:2-4',1,'Who am I?','["As a baby I was hidden in an ark of bulrushes.", "I was raised in Pharaoh''s household.", "I saw a bush burn without being consumed.", "I led Israel out of Egypt."]'::jsonb,'["Moses", "Aaron", "Joseph", "Joshua"]'::jsonb,0,'God called to Moses out of the midst of the burning bush.','Look in Exodus.',null,null,'KJV',array['moses','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed. And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt. And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-ruth','whoami',8,1,16,16,'Ruth 1:16',2,'Who am I?','["I was a woman of Moab.", "I told my mother-in-law: whither thou goest, I will go.", "I gleaned in the fields of Boaz.", "I became an ancestor of King David."]'::jsonb,'["Naomi", "Ruth", "Rahab", "Orpah"]'::jsonb,1,'Ruth said to Naomi, "Whither thou goest, I will go."','Look in Ruth.',null,null,'KJV',array['ruth','Ruth']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-samuel','whoami',9,3,10,10,'1 Samuel 3:10',2,'Who am I?','["My mother Hannah prayed for me at Shiloh.", "As a boy I served Eli the priest.", "I heard the LORD call my name in the night.", "I anointed both Saul and David."]'::jsonb,'["Nathan", "Eli", "Gad", "Samuel"]'::jsonb,3,'The LORD came and called, "Samuel, Samuel."','Look in 1 Samuel.',null,null,'KJV',array['samuel','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-samson','whoami',7,16,30,30,'Judges 16:30',1,'Who am I?','["I was a Nazarite from birth.", "I tore a young lion with my bare hands.", "Delilah learned the secret of my strength.", "I pulled down the house where the Philistines gathered."]'::jsonb,'["Samson", "Gideon", "Saul", "Jephthah"]'::jsonb,0,'Samson bowed himself with all his might and the house fell.','Look in Judges.',null,null,'KJV',array['samson','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-gideon','whoami',7,7,7,7,'Judges 7:7',3,'Who am I?','["An angel found me threshing wheat by a winepress.", "I tested God with a fleece.", "My army was reduced to three hundred men.", "We carried trumpets, pitchers and lamps."]'::jsonb,'["Joshua", "Gideon", "Barak", "Ehud"]'::jsonb,1,'The LORD said to Gideon, "By the three hundred men... will I save you."','Look in Judges.',null,null,'KJV',array['gideon','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-deborah','whoami',7,4,4,5,'Judges 4:4-5',3,'Who am I?','["I was a prophetess.", "I judged Israel under a palm tree in mount Ephraim.", "I summoned Barak to fight Sisera.", "A song of mine is recorded in Judges 5."]'::jsonb,'["Miriam", "Jael", "Huldah", "Deborah"]'::jsonb,3,'Deborah judged Israel and dwelt under the palm tree of Deborah.','Look in Judges.',null,null,'KJV',array['deborah','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time. And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-elisha','whoami',12,2,9,9,'2 Kings 2:9',3,'Who am I?','["I was ploughing with twelve yoke of oxen when I was called.", "I asked for a double portion of my master''s spirit.", "I took up the mantle that fell from Elijah.", "I told Naaman to wash in the Jordan seven times."]'::jsonb,'["Obadiah", "Gehazi", "Elijah", "Elisha"]'::jsonb,3,'Elisha said, "Let a double portion of thy spirit be upon me."','Look in 2 Kings.',null,null,'KJV',array['elisha','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-joseph','whoami',1,41,41,41,'Genesis 41:41',1,'Who am I?','["I was my father''s favourite son.", "My brothers sold me into slavery.", "I interpreted Pharaoh''s dreams.", "I was set over all the land of Egypt."]'::jsonb,'["Moses", "Judah", "Joseph", "Benjamin"]'::jsonb,2,'Pharaoh said to Joseph, "I have set thee over all the land of Egypt."','Look in Genesis.',null,null,'KJV',array['joseph','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-abraham','whoami',1,22,1,2,'Genesis 22:1-2',1,'Who am I?','["I left Ur of the Chaldees.", "God changed my name.", "My wife laughed at God''s promise of a son.", "God tested me in the land of Moriah."]'::jsonb,'["Abraham", "Isaac", "Jacob", "Lot"]'::jsonb,0,'God tempted (tested) Abraham and sent him to the land of Moriah.','Look in Genesis.',null,null,'KJV',array['abraham','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jacob','whoami',1,32,28,28,'Genesis 32:28',1,'Who am I?','["I was born holding my twin brother''s heel.", "I bought my brother''s birthright with pottage.", "I dreamed of a ladder reaching to heaven.", "God renamed me Israel."]'::jsonb,'["Isaac", "Laban", "Jacob", "Esau"]'::jsonb,2,'"Thy name shall be called no more Jacob, but Israel."','Look in Genesis.',null,null,'KJV',array['jacob','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-esau','whoami',1,25,30,33,'Genesis 25:30-33',2,'Who am I?','["I was a cunning hunter.", "I was born red and hairy.", "I sold my birthright for a meal.", "I am also called Edom."]'::jsonb,'["Ishmael", "Nimrod", "Jacob", "Esau"]'::jsonb,3,'Esau sold his birthright unto Jacob.','Look in Genesis.',null,null,'KJV',array['esau','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Esau said to Jacob, Feed me, I pray thee, with that same red pottage; for I am faint: therefore was his name called Edom. And Jacob said, Sell me this day thy birthright. And Esau said, Behold, I am at the point to die: and what profit shall this birthright do to me? And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-joshua','whoami',6,24,15,15,'Joshua 24:15',1,'Who am I?','["I was one of twelve men sent to spy out Canaan.", "I succeeded Moses as leader.", "The walls of Jericho fell when the people shouted.", "I said: As for me and my house, we will serve the LORD."]'::jsonb,'["Joshua", "Caleb", "Gideon", "Aaron"]'::jsonb,0,'Joshua 24:15: "As for me and my house, we will serve the LORD."','Look in Joshua.',null,null,'KJV',array['joshua','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-rahab','whoami',6,2,1,18,'Joshua 2:1-18',2,'Who am I?','["My house was upon the town wall of Jericho.", "I hid two Israelite spies.", "I let them down by a cord through a window.", "A line of scarlet thread marked my home."]'::jsonb,'["Rahab", "Jael", "Deborah", "Ruth"]'::jsonb,0,'The spies told Rahab to bind the scarlet thread in the window.','Look in Joshua.',null,null,'KJV',array['rahab','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there. And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country. And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country. And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were: And it came to pass about the time of shutting of the gate, when it was …') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-david','whoami',9,16,23,23,'1 Samuel 16:23',1,'Who am I?','["I was the youngest son of Jesse.", "I played the harp for King Saul.", "I defeated Goliath.", "I became king over Israel."]'::jsonb,'["Saul", "Jonathan", "David", "Solomon"]'::jsonb,2,'David took an harp and played, so Saul was refreshed.','Look in 1 Samuel.',null,null,'KJV',array['david','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-saul','whoami',9,9,2,2,'1 Samuel 9:2',2,'Who am I?','["I was of the tribe of Benjamin.", "From my shoulders upward I was higher than any of the people.", "Samuel anointed me as Israel''s first king.", "I consulted a woman at Endor."]'::jsonb,'["Absalom", "Jonathan", "David", "Saul"]'::jsonb,3,'Saul was "higher than any of the people" from his shoulders upward.','Look in 1 Samuel.',null,null,'KJV',array['saul','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-solomon','whoami',11,3,10,12,'1 Kings 3:10-12',1,'Who am I?','["My mother was Bathsheba.", "I asked God for an understanding heart.", "I built the temple in Jerusalem.", "I judged between two women who both claimed one baby."]'::jsonb,'["David", "Rehoboam", "Solomon", "Hezekiah"]'::jsonb,2,'God gave Solomon "a wise and an understanding heart."','Look in 1 Kings.',null,null,'KJV',array['solomon','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And the speech pleased the Lord, that Solomon had asked this thing. And God said unto him, Because thou hast asked this thing, and hast not asked for thyself long life; neither hast asked riches for thyself, nor hast asked the life of thine enemies; but hast asked for thyself understanding to discern judgment; Behold, I have done according to thy words: lo, I have given thee a wise and an understanding heart; so that there was none like thee before thee, neither after thee shall any arise like unto thee.') on conflict (id) do nothing;
