insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-daniel','whoami',27,6,23,23,'Daniel 6:23',1,'Who am I?','["I was taken captive to Babylon as a young man.", "I purposed not to defile myself with the king''s meat.", "I read the writing on the wall.", "I was delivered from the den of lions."]'::jsonb,'["Nehemiah", "Ezekiel", "Daniel", "Jeremiah"]'::jsonb,2,'Daniel was taken up out of the den, and no manner of hurt was found upon him.','Look in Daniel.',null,null,'KJV',array['daniel','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-esther','whoami',17,4,16,16,'Esther 4:16',1,'Who am I?','["I was raised by my cousin Mordecai.", "I became queen in Persia.", "I said: If I perish, I perish.", "The feast of Purim remembers my people''s deliverance."]'::jsonb,'["Deborah", "Esther", "Vashti", "Ruth"]'::jsonb,1,'Esther resolved to go in unto the king, "and if I perish, I perish."','Look in Esther.',null,null,'KJV',array['esther','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish.') on conflict (id) do nothing;
