insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jeremiah','whoami',24,1,5,6,'Jeremiah 1:5-6',3,'Who am I?','["God said He knew me before He formed me in the belly.", "I protested that I was only a child.", "I was let down into a dungeon full of mire.", "Baruch wrote my words on a roll."]'::jsonb,'["Jeremiah", "Daniel", "Isaiah", "Ezekiel"]'::jsonb,0,'God told Jeremiah, "Before I formed thee in the belly I knew thee." Tradition calls him the weeping prophet.','Look in Jeremiah.',null,null,'KJV',array['jeremiah','Jeremiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations. Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child.') on conflict (id) do nothing;
