insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-john_baptist','whoami',40,3,4,4,'Matthew 3:4',1,'Who am I?','["My father Zacharias was a priest.", "I wore raiment of camel''s hair.", "I ate locusts and wild honey.", "I baptized Jesus in the Jordan."]'::jsonb,'["Peter", "Andrew", "John the Baptist", "Elijah"]'::jsonb,2,'John had raiment of camel''s hair and his meat was locusts and wild honey.','Look in Matthew.',null,null,'KJV',array['john_baptist','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-peter','whoami',40,26,75,75,'Matthew 26:75',1,'Who am I?','["I was a fisherman, the brother of Andrew.", "Jesus called me to become a fisher of men.", "I walked on the water toward Jesus.", "I denied Jesus three times before the cock crew."]'::jsonb,'["Peter", "John", "Andrew", "Thomas"]'::jsonb,0,'Peter remembered Jesus'' words, "Before the cock crow, thou shalt deny me thrice."','Look in Matthew.',null,null,'KJV',array['peter','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-thomas','whoami',43,20,28,28,'John 20:28',2,'Who am I?','["I was one of the twelve, called Didymus.", "I was absent when Jesus first appeared to the disciples.", "I wanted to see the print of the nails.", "I said: My Lord and my God."]'::jsonb,'["Thomas", "Philip", "Bartholomew", "Matthew"]'::jsonb,0,'Thomas answered and said unto him, "My Lord and my God."','Look in John.',null,null,'KJV',array['thomas','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Thomas answered and said unto him, My Lord and my God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-zacchaeus','whoami',42,19,2,4,'Luke 19:2-4',1,'Who am I?','["I was chief among the publicans.", "I was rich.", "I was little of stature.", "I climbed a sycomore tree to see Jesus."]'::jsonb,'["Zacchaeus", "Matthew", "Bartimaeus", "Nicodemus"]'::jsonb,0,'Zacchaeus climbed up into a sycomore tree to see Jesus.','Look in Luke.',null,null,'KJV',array['zacchaeus','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature. And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-nicodemus','whoami',43,3,1,3,'John 3:1-3',2,'Who am I?','["I was a Pharisee and a ruler of the Jews.", "I came to Jesus by night.", "Jesus told me I must be born again.", "I brought myrrh and aloes for Jesus'' burial."]'::jsonb,'["Joseph of Arimathaea", "Gamaliel", "Zacchaeus", "Nicodemus"]'::jsonb,3,'Jesus told Nicodemus, "Except a man be born again, he cannot see the kingdom of God."','Look in John.',null,null,'KJV',array['nicodemus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews: The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him. Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-lazarus','whoami',43,11,43,44,'John 11:43-44',1,'Who am I?','["I lived in Bethany.", "My sisters were Mary and Martha.", "Jesus wept near my grave.", "Jesus called me out of the tomb."]'::jsonb,'["Bartimaeus", "Simon", "Jairus", "Lazarus"]'::jsonb,3,'Jesus cried with a loud voice, "Lazarus, come forth."','Look in John.',null,null,'KJV',array['lazarus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-martha','whoami',42,10,38,41,'Luke 10:38-41',3,'Who am I?','["I lived in Bethany with my sister and brother.", "I was cumbered about much serving.", "Jesus said my sister had chosen the good part.", "I welcomed Jesus into my house."]'::jsonb,'["Martha", "Mary Magdalene", "Salome", "Joanna"]'::jsonb,0,'"Martha was cumbered about much serving."','Look in Luke.',null,null,'KJV',array['martha','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house. And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word. But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me. And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-paul','whoami',44,9,3,4,'Acts 9:3-4',1,'Who am I?','["I was born in Tarsus.", "I once persecuted the church.", "A light from heaven blinded me near Damascus.", "I wrote many letters to the churches."]'::jsonb,'["Barnabas", "Stephen", "Silas", "Paul"]'::jsonb,3,'Near Damascus a voice said, "Saul, Saul, why persecutest thou me?" He is later called Paul.','Look in Acts.',null,null,'KJV',array['paul','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-stephen','whoami',44,7,58,59,'Acts 7:58-59',2,'Who am I?','["I was one of seven chosen to serve the church.", "I was full of faith and power.", "As I spoke I saw the heavens opened.", "I was stoned while a young man named Saul watched."]'::jsonb,'["Barnabas", "Stephen", "James", "Philip"]'::jsonb,1,'The witnesses laid their clothes at Saul''s feet, and they stoned Stephen.','Look in Acts.',null,null,'KJV',array['stephen','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul. And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-barnabas','whoami',44,4,36,37,'Acts 4:36-37',3,'Who am I?','["My name is interpreted ''the son of consolation''.", "I sold land and laid the money at the apostles'' feet.", "I brought Saul to the apostles in Jerusalem.", "I travelled with Paul on his first missionary journey."]'::jsonb,'["Timothy", "Barnabas", "Mark", "Silas"]'::jsonb,1,'Joses was surnamed Barnabas, "the son of consolation."','Look in Acts.',null,null,'KJV',array['barnabas','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus, Having land, sold it, and brought the money, and laid it at the apostles’ feet.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-lydia','whoami',44,16,14,15,'Acts 16:14-15',3,'Who am I?','["I was a seller of purple.", "I came from the city of Thyatira.", "I heard Paul speak by a riverside at Philippi.", "My household was baptized."]'::jsonb,'["Dorcas", "Priscilla", "Lydia", "Phebe"]'::jsonb,2,'Lydia, a seller of purple, of the city of Thyatira, heard Paul.','Look in Acts.',null,null,'KJV',array['lydia','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul. And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-timothy','whoami',55,1,2,5,'2 Timothy 1:2-5',3,'Who am I?','["My grandmother Lois and mother Eunice shared unfeigned faith.", "I was Paul''s young companion.", "Paul called me his dearly beloved son.", "Two New Testament letters are addressed to me."]'::jsonb,'["Silas", "Titus", "Timothy", "Luke"]'::jsonb,2,'Paul remembered the faith in Lois and Eunice, and in Timothy.','Look in 2 Timothy.',null,null,'KJV',array['timothy','2 Timothy']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord. I thank God, whom I serve from my forefathers with pure conscience, that without ceasing I have remembrance of thee in my prayers night and day; Greatly desiring to see thee, being mindful of thy tears, that I may be filled with joy; When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-adam','whoami',1,2,19,20,'Genesis 2:19-20',1,'Who am I?','["I was formed of the dust of the ground.", "I gave names to the animals.", "I lived in the garden of Eden.", "My wife was Eve."]'::jsonb,'["Enoch", "Cain", "Seth", "Adam"]'::jsonb,3,'"Adam gave names to all cattle, and to the fowl of the air."','Look in Genesis.',null,null,'KJV',array['adam','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-16", "human_review": "pending"}'::jsonb,'And out of the ground the LORD God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof. And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him.') on conflict (id) do nothing;
